/**
 * Create Questions and Assign For Review Post-Action
 * Reads AI-generated outputs/questions.json, creates question subtasks in Jira,
 * labels the parent ticket, and assigns it for review.
 *
 * questions.json format:
 * [
 *   {
 *     "summary": "Clarify requirements",          // [Q] prefix added automatically if missing
 *     "priority": "High",
 *     "description": "outputs/questions/question-1.md",
 *     "answer": "..."                              // optional, pre-filled answer
 *   }
 * ]
 */

const { extractTicketKey } = require('./common/jiraHelpers.js');
const { buildSummary } = require('./common/aiResponseParser.js');
const configLoader = require('./configLoader.js');
const scmModule = require('./common/scm.js');
const autoStart = require('./common/autoStart.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const outputFiles = require('./common/outputFiles.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

/**
 * Ensure summary starts with [Q] prefix
 */
function ensureQPrefix(summary) {
    if (!summary || summary.indexOf('[Q]') === 0) {
        return summary;
    }
    return '[Q] ' + summary;
}

// ── Pure decision/build helpers extracted from action() (gh-1038) ────────────
// No tracker/SCM/file side effects — kept separate so action()'s complexity
// drops and each decision can be unit-tested directly.

/**
 * WIP label for the workflow context, or null when no contextId is set.
 */
function buildWipLabel(metadata) {
    return metadata && metadata.contextId
        ? metadata.contextId + '_wip'
        : null;
}

/**
 * Agent id from the job metadata, defaulting to the story_questions workflow.
 */
function resolveAgentId(metadata) {
    return (metadata && metadata.agentId) || 'story_questions';
}

/**
 * Effective customParams: jobParams.customParams wins over params.customParams.
 */
function resolveActionCustomParams(params) {
    return (params.jobParams && params.jobParams.customParams) || params.customParams || {};
}

/**
 * Priority-name mapping: customParams > jobParamPatches[agentId] > project config.
 * @returns {Object|null} The resolved map, or null when none is configured.
 */
function resolvePriorityMap(customParams, projectConfig, agentId) {
    var jobParamPatch = projectConfig.jobParamPatches && projectConfig.jobParamPatches[agentId];
    return customParams.priorityMap
        || (jobParamPatch && jobParamPatch.customParams && jobParamPatch.customParams.priorityMap)
        || projectConfig.priorityMap
        || null;
}

/**
 * autoStartQuestionAnswer accepts both boolean true and the string 'true'.
 */
function shouldAutoStartQuestionAnswer(customParams) {
    return customParams.autoStartQuestionAnswer === true ||
        customParams.autoStartQuestionAnswer === 'true';
}

/**
 * Result message for the fatal CLI/provider error path.
 */
function buildCliFailureResult(cliErrorMessage) {
    return {
        success: false,
        error: 'CLI/provider failure: ' + cliErrorMessage,
        createdQuestions: []
    };
}

/**
 * Success-path result message, honest about the stage transition outcome.
 */
function buildActionMessage(ticketKey, stageOutcome, createdCount) {
    return stageOutcome === 'moved'
        ? 'Ticket ' + ticketKey + ' moved to PO Review, created ' + createdCount + ' question subtask(s)'
        : stageOutcome === 'marked'
            ? 'Ticket ' + ticketKey + ' marked stage PO Review (transition rejected), created ' + createdCount + ' question subtask(s)'
            : 'Ticket ' + ticketKey + ' NOT moved to PO Review (transition failed), created ' + createdCount + ' question subtask(s)';
}

/**
 * Per-question entry of the createdQuestions result list.
 */
function buildCreatedTicketReport(entry, key) {
    return {
        summary: ensureQPrefix(entry.summary || ''),
        priority: entry.priority,
        key: key,
        success: !!key
    };
}

/**
 * The Jira Server/DC assign failure mentions 'accountId' — those instances
 * want a silent skip instead of a noisy warning.
 */
function isAccountIdUnsupportedError(assignError) {
    var assignMsg = String(assignError && (assignError.message || assignError));
    return assignMsg.indexOf('accountId') !== -1;
}

/**
 * Read and parse outputs/questions.json
 * @returns {Array} Array of question entries, or empty array on error
 */
function readQuestionsJson() {
    try {
        var raw = file_read('outputs/questions.json');
        if (!raw || raw.trim() === '') {
            console.warn('outputs/questions.json is empty');
            return [];
        }
        var parsed = JSON.parse(raw);
        // Handle both plain array [...] and wrapped {"questions": [...]} formats
        if (!Array.isArray(parsed)) {
            if (parsed && Array.isArray(parsed.questions)) {
                console.warn('outputs/questions.json was wrapped in {"questions":[...]} — using inner array. Agent should write a plain JSON array.');
                return parsed.questions;
            }
            console.warn('outputs/questions.json is not an array');
            return [];
        }
        return parsed;
    } catch (error) {
        console.error('Failed to read/parse outputs/questions.json:', error);
        return [];
    }
}

/**
 * Read a description file, falling back to the entry summary
 */
function readDescriptionFile(filePath, fallbackSummary) {
    if (!filePath) {
        return fallbackSummary || '';
    }
    try {
        var content = file_read(filePath);
        if (content && content.trim() !== '') {
            return content;
        }
    } catch (error) {
        console.warn('Could not read description file ' + filePath + ':', error);
    }
    return fallbackSummary || '';
}

/**
 * When the agent decides no clarifying questions are needed, it must still
 * explain why in outputs/response.md. Post that explanation as a Jira comment
 * so a human reviewer sees the reasoning instead of a silent skip.
 * If the agent did NOT write a response.md, post a visible warning instead of
 * silently moving the ticket forward with zero explanation.
 */
function postNoQuestionsExplanation(ticketKey) {
    var explanation = outputFiles.readOutputFile('response.md', { ticketKey: ticketKey });
    if (explanation && explanation.trim()) {
        try {
            getTracker().postComment(ticketKey, 'h3. \u2139\ufe0f No clarifying questions needed\n\n' + explanation.trim());
            console.log('Posted no-questions explanation from outputs/response.md');
        } catch (e) {
            console.warn('Failed to post no-questions explanation comment:', e);
        }
        return;
    }

    console.warn('No questions were raised AND outputs/response.md is missing/empty — posting fallback warning comment.');
    try {
        getTracker().postComment(ticketKey, 'h3. \u26a0\ufe0f No clarifying questions raised \u2014 no explanation provided\n\n' +
                'The AI agent did not create any clarifying questions for this ticket, and did not write ' +
                '{{outputs/response.md}} explaining why. Please verify manually whether the story is actually ' +
                'clear enough to proceed, or re-run the agent.');
    } catch (e) {
        console.warn('Failed to post fallback no-questions warning comment:', e);
    }
}

/**
 * Create a single question subtask in Jira
 * @param {Object} entry - Entry from questions.json
 * @param {string} parentKey - Parent story ticket key
 * @param {string} projectKey - Jira project key
 * @param {Object} jiraConfig - Resolved jira config (issueTypes, labels, questions)
 * @param {Object} [priorityMap] - Optional mapping of agent priority names to project-specific names
 * @returns {string|null} Created ticket key or null on failure
 */
function createQuestion(entry, parentKey, projectKey, jiraConfig, priorityMap) {
    var summary = ensureQPrefix(buildSummary(entry.summary, 0));
    var description = readDescriptionFile(entry.description, entry.summary);
    var questionIssueType = jiraConfig.issueTypes.SUBTASK;
    var questionLabel = jiraConfig.labels.QUESTION;
    var answerField = jiraConfig.questions.answerField;

    var fieldsJson = {
        summary: summary,
        description: description,
        issuetype: { name: questionIssueType },
        parent: { key: parentKey },
        labels: [questionLabel]
    };

    if (entry.priority) {
        var resolvedPriority = (priorityMap && priorityMap[entry.priority]) || entry.priority;
        fieldsJson.priority = { name: resolvedPriority };
    }

    if (entry.answer) {
        fieldsJson[answerField] = entry.answer;
    }

    try {
        var tracker = getTracker();
        var result;
        if (tracker.provider() === 'ado') {
            // agents#870: fieldsJson above is Jira-shaped (issuetype/parent/summary); createTicketWithFields on
            // ADO needs ADO field names and would throw. Create the work item, link it to its parent and add
            // the question label through the tracker instead. The work item type is jira.questions.workItemType
            // (default 'Task' — the child type of a PBI/Bug in the standard ADO processes).
            var adoType = (jiraConfig.questions && jiraConfig.questions.workItemType) || 'Task';
            result = tracker.createTicketWithParent(projectKey, adoType, summary, description, parentKey, { labels: [questionLabel] });
            if (result && entry.priority) {
                try {
                    tracker.setPriority(result, (priorityMap && priorityMap[entry.priority]) || entry.priority);
                } catch (priorityError) {
                    console.warn('Could not set priority on question ' + result + ' (non-fatal):', priorityError);
                }
            }
        } else {
            result = tracker.createTicketWithFields(projectKey, fieldsJson);
        }
        var key = (typeof result === 'string' && result) ? result : extractTicketKey(result);
        console.log('Created question subtask ' + (key || '(unknown key)') + ': ' + summary);
        return key;
    } catch (error) {
        console.error('Failed to create question subtask "' + summary + '":', error);
        return null;
    }
}

function loadConfigSafe(params) {
    try { return configLoader.loadProjectConfig(params); } catch (e) { return null; }
}

function action(params) {
    try {
        var ticketKey = params.ticket.key;
        var projectKey = ticketKey.split('-')[0];
        initTracker(loadConfigSafe(params), (params.jobParams && params.jobParams.customParams) || {});
        var initiatorId = params.initiator;
        var wipLabel = buildWipLabel(params.metadata);

        // The CLI/AI-provider call can fail (missing binary, provider outage, HTTP 5xx, ...)
        // while outputType is 'none' and skipAIProcessing is true — in that setup Teammate's
        // own "skip field update, post error comment" safety net never runs (it's gated behind
        // outputType != none), so this is the only place left to detect the failure. Do NOT
        // let a fatal CLI error fall through to the "0 questions were raised" path below: that
        // path unconditionally labels, assigns and moves the ticket to PO Review as if the AI
        // had genuinely reviewed the story and found it clear, which silently hides the failure.
        if (params.currentCliHasFatalError) {
            var cliErrorMessage = params.currentCliErrorMessage || 'unknown CLI/provider error';
            console.error('Fatal CLI/provider error for ' + ticketKey + ' — leaving the ticket untouched instead of treating it as "no questions needed": ' + cliErrorMessage);
            try {
                getTracker().postComment(ticketKey, 'h3. \u274c AI agent run failed \u2014 ticket left unchanged\n\n' +
                        'The underlying CLI/AI provider call failed, so no clarifying questions could be generated:\n\n' +
                        '{code}' + cliErrorMessage + '{code}\n\n' +
                        'This ticket was NOT moved to PO Review and no labels were changed. Please retry the agent.');
            } catch (commentError) {
                console.warn('Failed to post CLI-failure comment:', commentError);
            }
            return buildCliFailureResult(cliErrorMessage);
        }

        var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        var jiraConfig = projectConfig.jira;
        var labels = projectConfig.labels;
        var customParams = resolveActionCustomParams(params);
        initTracker(projectConfig, customParams);
        var agentId = resolveAgentId(params.metadata);
        var priorityMap = resolvePriorityMap(customParams, projectConfig, agentId);

        console.log('Processing question creation for:', ticketKey);
        if (priorityMap) console.log('Priority map active:', JSON.stringify(priorityMap));

        // 1. Read questions.json
        var questions = readQuestionsJson();
        console.log('Found ' + questions.length + ' entries in questions.json');

        if (questions.length === 0) {
            console.log('No questions to create — skipping ticket creation.');
            postNoQuestionsExplanation(ticketKey);
        }

        // 2. Create question subtasks
        var createdTickets = [];
        questions.forEach(function (entry) {
            var key = createQuestion(entry, ticketKey, projectKey, Object.assign({}, jiraConfig, { labels: labels }), priorityMap);
            createdTickets.push(buildCreatedTicketReport(entry, key));
        });

        var failedCount = createdTickets.filter(function (t) { return !t.success; }).length;
        if (failedCount > 0) {
            throw new Error(
                'Failed to create ' + failedCount + ' of ' + createdTickets.length +
                ' question subtask(s) under ' + ticketKey +
                ' — check the errors logged above for details'
            );
        }

        // 3. Add ai_questions_asked label to parent ticket
        try {
            getTracker().addLabel(ticketKey, labels.AI_QUESTIONS_ASKED);
        } catch (labelError) {
            console.warn('Failed to add ' + labels.AI_QUESTIONS_ASKED + ' label:', labelError);
        }

        // 4. Add ai_generated label
        try {
            getTracker().addLabel(ticketKey, labels.AI_GENERATED);
        } catch (labelError) {
            console.warn('Failed to add ' + labels.AI_GENERATED + ' label:', labelError);
        }

        // 5. Assign to initiator
        try {
            if (initiatorId) {
                getTracker().assignTo(ticketKey, initiatorId);
                console.log('Assigned ' + ticketKey + ' to initiator');
            } else {
                console.log('No initiator id — skipping assign');
            }
        } catch (assignError) {
            if (isAccountIdUnsupportedError(assignError)) {
                console.warn('Skipping assign — accountId not supported in this Jira instance (Server/DC uses username)');
            } else {
                console.warn('Failed to assign ticket:', assignError);
            }
        }

        // 6. Move parent story to PO Review (agents#856: with stageFallback 'label' a rejected transition
        //    leaves a stage_po_review marker instead of losing the hand-off; default keeps the old behaviour)
        var stageOutcome = 'failed';
        try {
            var stageResult = getTracker().moveToStatusOrMark(ticketKey, jiraConfig.statuses.PO_REVIEW, 'PO_REVIEW');
            if (stageResult && stageResult.marked) {
                stageOutcome = 'marked';
                console.log('Marked ' + ticketKey + ' with ' + stageResult.label + ' (transition to PO Review rejected)');
            } else {
                stageOutcome = 'moved';
                console.log('Moved ' + ticketKey + ' to PO Review');
            }
        } catch (statusError) {
            console.warn('Failed to move ' + ticketKey + ' to PO Review:', statusError);
        }

        // 7. Remove WIP label if present
        if (wipLabel) {
            try {
                getTracker().removeLabel(ticketKey, wipLabel);
                console.log('Removed WIP label "' + wipLabel + '" from ' + ticketKey);
            } catch (wipError) {
                console.warn('Failed to remove WIP label:', wipError);
            }
        }

        // 8. Optionally auto-start question answering for each created question
        var autoStartQuestionAnswer = shouldAutoStartQuestionAnswer(customParams);
        var questionAnswerConfigFile = customParams.autoStartQuestionAnswerConfigFile;
        if (autoStartQuestionAnswer && questionAnswerConfigFile) {
            try {
                var scm = scmModule.createScm(projectConfig);
                createdTickets
                    .filter(function (ticket) { return ticket.success && ticket.key; })
                    .forEach(function (ticket) {
                        autoStart.triggerConfiguredWorkflowForTicket({
                            scm: scm,
                            config: projectConfig,
                            ticketKey: ticket.key,
                            customParams: customParams,
                            configFile: questionAnswerConfigFile,
                            label: 'question answer',
                            stripKeys: ['autoStartQuestionAnswer', 'autoStartQuestionAnswerConfigFile']
                        });
                    });
            } catch (e) {
                console.warn('⚠️ autoStartQuestionAnswer trigger failed:', e.message || e);
            }
        }

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            message: buildActionMessage(ticketKey, stageOutcome, createdTickets.length),
            stageStatus: stageOutcome,
            createdQuestions: createdTickets
        };

    } catch (error) {
        console.error('Error in createQuestionsAndAssignForReview:', error);
        throw error;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        buildWipLabel: buildWipLabel,
        resolveAgentId: resolveAgentId,
        resolveActionCustomParams: resolveActionCustomParams,
        resolvePriorityMap: resolvePriorityMap,
        shouldAutoStartQuestionAnswer: shouldAutoStartQuestionAnswer,
        buildCliFailureResult: buildCliFailureResult,
        buildActionMessage: buildActionMessage,
        buildCreatedTicketReport: buildCreatedTicketReport,
        isAccountIdUnsupportedError: isAccountIdUnsupportedError
    };
}

/**
 * Fetch Questions To Input Pre-CLI Action
 * Fetches existing question subtasks for the current story ticket and writes
 * them to the input folder before the CLI agent runs.
 * Receives params.inputFolderPath from DMTools after input folder creation.
 *
 * Tracker-aware (gh-770): the provider is probed via common/trackers.js and
 * the JQL is only fired on Jira — question subtasks (issuetype + answer
 * custom field) are a Jira concept, and the JQL is meaningless on GitHub/ADO
 * trackers, where it silently returned empty on every dev/rework leg.
 *
 * Configurable via .dmtools/config.js:
 *   jira.questions.fetchJql   — JQL to find question subtasks ({ticketKey} placeholder)
 *   jira.questions.answerField — Jira custom field name for the answer (default: 'Answer')
 */

var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');
// Load-time require (gh-823): a deferred require would resolve against the
// pack js/ root only — hoist every require to the top of the module.
var fetchParentContextToInput = require('./fetchParentContextToInput.js');

function hasAnswerValue(fields, key) {
    return Object.prototype.hasOwnProperty.call(fields, key)
        && fields[key] !== undefined
        && fields[key] !== null;
}

function getAnswerValue(fields, answerField) {
    if (!fields || !answerField) {
        return null;
    }

    var answerFieldLower = answerField.toLowerCase();
    if (hasAnswerValue(fields, answerField)) {
        return fields[answerField];
    }

    if (hasAnswerValue(fields, answerFieldLower)) {
        return fields[answerFieldLower];
    }

    var customFieldSuffix = answerField.indexOf('customfield_') === 0
        ? '(' + answerFieldLower + ')'
        : null;
    var transformedFriendlyPrefix = answerFieldLower + ' (';

    for (var key in fields) {
        if (!Object.prototype.hasOwnProperty.call(fields, key)) {
            continue;
        }

        var keyLower = key.toLowerCase();
        if (keyLower === answerFieldLower && hasAnswerValue(fields, key)) {
            return fields[key];
        }
        if (customFieldSuffix && keyLower.slice(-customFieldSuffix.length) === customFieldSuffix && hasAnswerValue(fields, key)) {
            return fields[key];
        }
        if (keyLower.indexOf(transformedFriendlyPrefix) === 0 && keyLower.slice(-1) === ')' && hasAnswerValue(fields, key)) {
            return fields[key];
        }
    }

    return null;
}

/**
 * Build the question-subtask fetch plan for the ticket's tracker (gh-770).
 *
 * The configured query (`jira.questions.fetchJql`) is Jira-speak —
 * "parent = {ticketKey} AND issuetype = Subtask" — which routes fine on a
 * GitHub-backed deployment but is meaningless there: it silently returns
 * empty and the leg logs "Failed to fetch questions, continuing without
 * file". Question subtasks (issuetype + answer custom field) are a Jira
 * concept, so the JQL is only fired on the jira provider; github/ado skip
 * with an explicit reason instead of firing a query that can never match.
 *
 * @param {string} provider        - tracker provider (createTracker().provider())
 * @param {Object} questionsConfig - config.jira.questions (fetchJql, answerField)
 * @param {string} ticketKey       - the ticket whose questions are fetched
 * @returns {Object} { skip: false, jql } | { skip: true, reason }
 */
function questionsFetchPlan(provider, questionsConfig, ticketKey) {
    var p = String(provider || 'jira').toLowerCase();
    var fetchJql = String((questionsConfig && questionsConfig.fetchJql) || '');
    if (p === 'ado' && /^\s*SELECT\b/i.test(fetchJql)) {
        // agents#871: the project supplied a WIQL query for jira.questions.fetchJql — it is native to this
        // tracker, so run it. The shipped default is Jira JQL and still takes the skip branch below.
        return {
            skip: false,
            jql: fetchJql.replace('{ticketKey}', ticketKey)
        };
    }
    if (p !== 'jira') {
        return {
            skip: true,
            reason: 'question subtasks are a Jira issue-type concept (' + fetchJql +
                ') — the query is Jira-speak and would silently return nothing on the ' +
                p + ' tracker' +
                (p === 'ado' ? '; set jira.questions.fetchJql to a WIQL query (SELECT ...) to fetch them on ADO' : '')
        };
    }
    return {
        skip: false,
        jql: questionsConfig.fetchJql.replace('{ticketKey}', ticketKey)
    };
}

var COMMENT_SENTINELS = { comment: true, comments: true, 'system.history': true };

function isCommentAnswerSentinel(answerField) {
    var norm = String(answerField || '').trim().toLowerCase();
    return Boolean(COMMENT_SENTINELS[norm]);
}

function buildQuestionSearchFields(provider, answerField) {
    if (String(provider || 'jira').toLowerCase() !== 'ado') {
        return ['key', 'summary', 'description', 'status', 'priority', answerField];
    }
    if (!answerField || isCommentAnswerSentinel(answerField)) {
        return ['key', 'summary', 'description', 'status', 'priority'];
    }
    return ['key', 'summary', 'description', 'status', 'priority', answerField];
}

function extractLatestCommentAnswer(comments) {
    var list = Array.isArray(comments) ? comments : [];
    for (var i = list.length - 1; i >= 0; i--) {
        var c = list[i];
        if (c && typeof c.body === 'string' && c.body.trim().length > 0) {
            return c.body;
        }
    }
    return null;
}

function fetchCommentAnswer(tracker, issueKey) {
    try {
        return extractLatestCommentAnswer(tracker.getComments(issueKey));
    } catch (e) {
        console.warn('Failed to fetch comments for question ' + issueKey + ':', e && e.message ? e.message : String(e));
        return null;
    }
}

function rawFieldsOf(issue) {
    var raw = issue && issue.raw;
    return raw ? raw.fields : null;
}

function resolveFieldAnswer(issue, answerField) {
    var direct = getAnswerValue(issue && issue.fields, answerField);
    return direct !== null ? direct : getAnswerValue(rawFieldsOf(issue), answerField);
}

function usesAdoCommentThread(provider, answerField) {
    return String(provider || 'jira').toLowerCase() === 'ado' && isCommentAnswerSentinel(answerField);
}

function resolveQuestionAnswer(tracker, provider, issue, answerField) {
    if (usesAdoCommentThread(provider, answerField)) {
        return fetchCommentAnswer(tracker, issue ? issue.key : '');
    }
    return resolveFieldAnswer(issue, answerField);
}

/**
 * Enrich input with parent story + [BA]/[SA]/[VD] context (non-fatal).
 *
 * gh-1112: preCliContentOutputSetup runs this step itself (fault-isolated
 * in its own chain) and suppresses this built-in call via skipParentContext
 * so the parent-context JQL is not fired twice per run.
 */
function fetchParentContextSafely(params) {
    if (params.skipParentContext) return;
    try {
        fetchParentContextToInput.action(params);
    } catch (e) {
        console.warn('fetchParentContextToInput failed (non-fatal):', e);
    }
}

function namedField(obj) {
    return obj ? obj.name : '';
}

function textOrEmpty(val) {
    return val || '';
}

function toQuestionEntry(tracker, provider, issue, answerField) {
    var f = (issue && issue.fields) || {};
    return {
        key: textOrEmpty(issue && issue.key),
        summary: textOrEmpty(f.summary),
        description: textOrEmpty(f.description),
        status: namedField(f.status),
        priority: namedField(f.priority),
        answer: resolveQuestionAnswer(tracker, provider, issue, answerField)
    };
}

function fetchAndWriteQuestions(tracker, provider, plan, answerField, folder) {
    var rawQuestions = tracker.searchIssues(plan.jql, {
        fields: buildQuestionSearchFields(provider, answerField)
    });
    var questions = [];
    for (var i = 0; i < rawQuestions.length; i++) {
        questions.push(toQuestionEntry(tracker, provider, rawQuestions[i], answerField));
    }
    console.log('Found ' + questions.length + ' question subtasks');
    // Wrap in object: file_write bridge auto-parses strings starting with '[' as ArrayList.
    file_write(folder + '/existing_questions.json', '{"questions":' + JSON.stringify(questions, null, 2) + '}');
    console.log('Wrote existing_questions.json to ' + folder);
}

/**
 * Pre-CLI action: fetch question subtasks into input folder
 *
 * @param {Object} params - Parameters from DMTools
 * @param {string} params.inputFolderPath - Path to the input folder for this run
 */
function action(params) {
    try {
        var folder = params.inputFolderPath;
        // Ticket key is always the last segment of the input folder path.
        var ticketKey = folder.split('/').pop();
        console.log('Fetching question subtasks for ' + ticketKey + '...');

        var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        var questionsConfig = projectConfig.jira.questions;
        var answerField = questionsConfig.answerField;

        // Probe the tracker provider once (gh-770): the same script then runs
        // unchanged on Jira / ADO / GitHub deployments.
        var customParams = (params.jobParams && params.jobParams.customParams) || params.customParams || {};
        var tracker = trackersModule.createTracker(projectConfig, customParams);
        var provider = tracker.provider();
        var plan = questionsFetchPlan(provider, questionsConfig, ticketKey);

        if (plan.skip) {
            console.warn('Skipping question subtask fetch — ' + plan.reason);
        } else try {
            fetchAndWriteQuestions(tracker, provider, plan, answerField, folder);
        } catch (fetchError) {
            // gh-802 AC3c: the host console renders a raw Error object as "{}"
            // (the cause was invisible in the logs) — log the CONTENT instead.
            var fetchErrorDetail = fetchError && fetchError.message
                ? fetchError.message
                : String(fetchError);
            console.error('Failed to fetch questions, continuing without file:', fetchErrorDetail);
        }
    } catch (error) {
        console.error('Error in fetchQuestionsToInput:', error);
    }

    fetchParentContextSafely(params);
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        getAnswerValue: getAnswerValue,
        hasAnswerValue: hasAnswerValue,
        questionsFetchPlan: questionsFetchPlan,
        fetchParentContextSafely: fetchParentContextSafely,
        isCommentAnswerSentinel: isCommentAnswerSentinel,
        buildQuestionSearchFields: buildQuestionSearchFields,
        extractLatestCommentAnswer: extractLatestCommentAnswer,
        resolveQuestionAnswer: resolveQuestionAnswer
    };
}

/**
 * Enhance SD API Description and Assess Action
 * Enhances SD API ticket descriptions with technical details, assesses implementation needs, 
 * and updates diagram field based on AI-generated content
 */

// Import common helper functions
const { extractTicketKey } = require('./common/jiraHelpers.js');
const { LABELS, DIAGRAM_DEFAULTS, DIAGRAM_FORMAT, JIRA_FIELDS } = require('./config.js');
var configLoader = null;
try { configLoader = require('./configLoader.js'); } catch (e) {}

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}
function resolveProjectConfig(params) {
    return configLoader ? configLoader.loadProjectConfig(params) : null;
}

/**
 * Parse AI response for SD API enhancement
 * Expects JSON object with description, apiSubtaskCreation boolean, and diagram string
 * 
 * @param {Object|string} response - AI response (should be JSON object)
 * @returns {Object} Parsed enhancement data or null if invalid
 */
function parseSDAPIEnhancementResponse(response) {
    // Handle string responses (parse JSON)
    if (typeof response === 'string') {
        try {
            response = JSON.parse(response);
        } catch (error) {
            console.error('Invalid JSON from AI:', error);
            return null;
        }
    }

    // Validate expected structure
    if (!response || typeof response !== 'object') {
        console.warn('AI response is not an object, got:', typeof response);
        return null;
    }

    // Validate required fields
    if (typeof response.description !== 'string' || 
        typeof response.apiSubtaskCreation !== 'boolean' ||
        typeof response.diagram !== 'string') {
        console.error('AI response missing required fields or wrong types:', response);
        return null;
    }

    // Basic validation for mermaid sequence diagram
    if (!response.diagram.trim()) {
        console.warn('Empty diagram provided');
        response.diagram = DIAGRAM_DEFAULTS.API_SEQUENCE;
    }

    return response;
}

/**
 * Update SD API ticket with enhanced content
 * 
 * @param {string} ticketKey - The ticket key to update
 * @param {Object} enhancementData - Parsed enhancement data from AI
 * @returns {Object} Update result
 */
function updateSDAPITicket(ticketKey, enhancementData) {
    const results = {
        descriptionUpdated: false,
        diagramUpdated: false,
        labelAdded: false,
        errors: []
    };

    try {
        // Update ticket description
        getTracker().updateDescription(ticketKey, enhancementData.description);
        results.descriptionUpdated = true;
        console.log('✅ Updated description for ' + ticketKey);
    } catch (error) {
        console.error('Failed to update description for ' + ticketKey + ':', error);
        results.errors.push('Description update failed: ' + error.toString());
    }

    try {
        // Update Diagrams field with mermaid sequence diagram wrapped in code tags for better visualization
        const wrappedDiagram = DIAGRAM_FORMAT.MERMAID_WRAPPER_START + enhancementData.diagram + DIAGRAM_FORMAT.MERMAID_WRAPPER_END;
        getTracker().updateField(ticketKey, JIRA_FIELDS.DIAGRAMS, wrappedDiagram);
        results.diagramUpdated = true;
        console.log('✅ Updated Diagrams field for ' + ticketKey);
    } catch (error) {
        console.error('Failed to update Diagrams field for ' + ticketKey + ':', error);
        results.errors.push('Diagrams field update failed: ' + error.toString());
    }

    try {
        // Add implementation assessment label if needed
        if (enhancementData.apiSubtaskCreation) {
            getTracker().addLabel(ticketKey, LABELS.NEEDS_API_IMPLEMENTATION);
            results.labelAdded = true;
            console.log('✅ Added needs_api_implementation label to ' + ticketKey);
        } else {
            console.log('ℹ️ No additional API implementation needed for ' + ticketKey);
        }
    } catch (error) {
        console.error('Failed to add implementation label to ' + ticketKey + ':', error);
        results.errors.push('Label addition failed: ' + error.toString());
    }

    return results;
}

function action(params) {
    try {
        const ticketKey = params.ticket.key;
        const initiatorId = params.initiator;
        initTracker(resolveProjectConfig(params), (params.jobParams && params.jobParams.customParams) || params.customParams || {});
        // Dynamically generate WIP label from contextId
        const wipLabel = params.metadata && params.metadata.contextId 
            ? params.metadata.contextId + '_wip' 
            : null;

        console.log("Processing SD API enhancement for ticket:", ticketKey);

        // Parse AI enhancement response
        const enhancementData = parseSDAPIEnhancementResponse(params.response);
        if (!enhancementData) {
            const errorMsg = 'Invalid AI response format for SD API enhancement';
            console.error(errorMsg);

            return {
                success: false,
                error: errorMsg
            };
        }

        // Update SD API ticket with enhanced content
        const updateResults = updateSDAPITicket(ticketKey, enhancementData);

        // Use common assignForReview function for post-processing
        const assignResult = getTracker().assignForReview(ticketKey, initiatorId, wipLabel);

        if (!assignResult.success) {
            return assignResult;
        }

        const successCount = (updateResults.descriptionUpdated ? 1 : 0) + 
                           (updateResults.diagramUpdated ? 1 : 0) + 
                           (updateResults.labelAdded ? 1 : 0);

        return {
            success: true,
            message: `Ticket ${ticketKey} enhanced, assigned, moved to In Review. Updates: ${successCount}/3 successful`,
            enhancementData: enhancementData,
            updateResults: updateResults
        };

    } catch (error) {
        console.error("❌ Error:", error);

        return {
            success: false,
            error: error.toString()
        };
    }
}


if (typeof module !== "undefined" && module.exports) {
    module.exports = { action };
}

/**
 * AI Response Parser
 * Simple utilities for AI responses - expecting stable, well-formatted responses
 */

const { SUMMARY_MAX_LENGTH } = require('../config.js');

/**
 * Parse AI response containing questions array
 * Expects clean JSON array format from AI
 * 
 * @param {Array|string} response - AI response (should be JSON array)
 * @returns {Array} Array of question objects
 */
function parseQuestionsResponse(response) {
    // Handle string responses (parse JSON)
    if (typeof response === 'string') {
        try {
            response = JSON.parse(response);
        } catch (error) {
            console.error('Invalid JSON from AI:', error);
            return [];
        }
    }

    // Expect array format
    if (!Array.isArray(response)) {
        console.warn('AI response is not an array, got:', typeof response);
        return [];
    }

    return response; // Trust AI to provide correct format
}

/**
 * Build ticket summary with length constraint
 * 
 * @param {string} summary - Summary from AI
 * @param {number} index - Index for fallback numbering
 * @returns {string} Summary (truncated if needed)
 */
function buildSummary(summary, index) {
    const text = summary || 'Follow-up question #' + (index + 1);
    return text.length <= SUMMARY_MAX_LENGTH ? text : text.slice(0, SUMMARY_MAX_LENGTH - 3) + '...';
}

/**
 * Build ticket description
 * 
 * @param {Object} question - Question object
 * @returns {string} Description text
 */
function buildDescription(question) {
    return question.description || 'Follow template from instructions.';
}

// Export functions for use by other modules
module.exports = {
    parseQuestionsResponse,
    buildSummary,
    buildDescription
};

